import ReachyKit
import ReachyMedia
import SwiftUI

/// The call framing's effects, beside `RootLifecycle` rather than inside it —
/// that body's own comment says it has no cyclomatic budget left. Everything
/// here is inert in previews and on macOS: the controller's facade no-ops off
/// iOS, and `previewMode` guards the rest.
///
/// What it does, in one place:
/// - keeps `RobotCallController` pointed at the connected robot;
/// - ends the call when the session under it goes away (robot asleep or
///   disconnected, stream failed, viewport target gone) — deliberately **not**
///   when the stream merely leaves `.streaming`, because `CameraSession`
///   self-heals through `.connecting` and the mic track comes back on its own;
/// - receives a Recents redial and routes call requests (Siri's included) —
///   Live tab, camera content, then unmute once the stream is up;
/// - donates the start-call intent each time a call actually starts.
struct RootCallLifecycle: ViewModifier {
    let session: RobotSession
    let viewport: ViewportModel
    let router: ReachyRouter
    let call: RobotCallController
    let remoteLink: RemoteRobotLink?

    /// `shared` for the reason `QuickActionInbox.shared` is: the intent that
    /// fills it runs with no initialiser to inject through.
    private let inbox = CallRequestInbox.shared

    @Environment(\.reachyPreviewMode) private var previewMode

    func body(content: Content) -> some View {
        content
            .onChange(of: connectedIdentity, initial: true) { _, identity in
                guard !previewMode else { return }
                call.robotChanged(id: identity?.deduplicationKey, name: identity?.name)
            }
            .onChange(of: callMustEnd) { _, mustEnd in
                guard !previewMode, mustEnd else { return }
                call.sessionBecameIneligible(failed: cameraHasFailed)
            }
            .onContinueUserActivity(CallActivity.activityType) { activity in
                guard !previewMode, let robotID = CallActivity.robotID(from: activity) else { return }
                inbox.receive(robotID: robotID)
            }
            .onChange(of: routingTrigger, initial: true) { _, _ in
                guard !previewMode else { return }
                routePendingRequest()
            }
            .onChange(of: call.donationCount) { _, _ in
                guard !previewMode, let active = call.activeCall else { return }
                CallActivity.donate(robotID: active.robotID, robotName: active.robotName)
            }
    }

    /// The identity through `.unreachable` too: a network blip must not read as
    /// a robot change and end the call — the same reading `publishHandoff`
    /// makes. Only the phases with no identity at all report none.
    private var connectedIdentity: RobotIdentity? {
        switch session.phase {
        case let .connected(identity), let .unreachable(identity): identity
        case .idle, .connecting: nil
        }
    }

    private var viewportTarget: ViewportModel.Source? {
        RootViewportTarget.source(session: session, remoteLink: remoteLink)
    }

    private var cameraHasFailed: Bool {
        if case .failed = viewport.cameraSession?.phase {
            return true
        }
        return false
    }

    private var callMustEnd: Bool {
        guard call.hasActiveCall else { return false }
        return viewportTarget == nil || !session.isAwake || cameraHasFailed
    }

    /// Everything a pending request waits on, in one `Equatable` value — the
    /// `EntityIndexTrigger` shape. A change to any of them re-runs the routing:
    /// the request arriving, the robot connecting, the stream coming up.
    private struct RoutingTrigger: Equatable {
        let pendingToken: Int?
        let robotID: String?
        let cameraIsStreaming: Bool
    }

    private var routingTrigger: RoutingTrigger {
        RoutingTrigger(
            pendingToken: inbox.pending?.token,
            robotID: connectedIdentity?.deduplicationKey,
            cameraIsStreaming: viewport.cameraSession?.phase == .streaming
        )
    }

    private func routePendingRequest() {
        guard let pending = inbox.pending else { return }
        guard !pending.request.isExpired(now: Date()) else {
            inbox.drop()
            return
        }
        switch CallRequestRouting.decide(
            requestRobotID: pending.request.robotID,
            connectedRobotID: connectedIdentity?.deduplicationKey,
            connectedRobotName: connectedIdentity?.name
        ) {
        case .waitForConnection:
            // Leave it pending; connecting re-fires the trigger and expiry
            // bounds the wait.
            break
        case .liveTabOnly:
            inbox.drop()
            router.tab = .live
        case .proceed:
            router.tab = .live
            guard session.hasCamera else {
                // A wired unit has no camera and therefore no call to place;
                // the Live tab saying so is the whole answer.
                inbox.drop()
                return
            }
            if viewport.content != .camera {
                viewport.setContent(.camera)
            }
            guard let camera = viewport.cameraSession, camera.phase == .streaming else {
                // Not up yet — the trigger fires again at `.streaming`.
                return
            }
            inbox.drop()
            call.startCall(for: camera)
        }
    }
}

import Foundation

/// Stable identity of a robot, established during the connection handshake.
///
/// Robots are identified by hardware ID, never by network address — one robot can
/// be reachable at several addresses at once (upstream issue #269).
public struct RobotIdentity: Hashable, Sendable, Codable {
    /// From `GET /api/daemon/hardware-id`. `nil` when the daemon reports none
    /// (simulation) — fall back to `name` for deduplication then.
    public var hardwareID: String?
    /// From `GET /api/daemon/robot-name`.
    public var name: String?
    /// Daemon version reported on handshake; drives graceful degradation for unknown fields.
    public var daemonVersion: String?

    public init(hardwareID: String? = nil, name: String? = nil, daemonVersion: String? = nil) {
        self.hardwareID = hardwareID
        self.name = name
        self.daemonVersion = daemonVersion
    }

    /// Stable key for deduplicating discovery results (issue #269 class of bugs).
    public var deduplicationKey: String {
        hardwareID ?? name ?? "unknown"
    }
}

import Foundation
#if os(iOS)
    import Intents
#endif

/// The sixth entry-point system, beside App Shortcuts, `ReachyQuickAction`,
/// `ReachySpotlightIndex`, `ReachyEntityIndex` and `ReachyHandoff` — and the
/// only one the *Phone app* drives. Each call started through
/// `RobotCallController` donates an `INStartCallIntent`, which is what gives a
/// Recents row its redial and Siri its suggestion; tapping that row relaunches
/// this app with the intent wrapped in an `NSUserActivity`, and
/// `RootCallLifecycle` turns it back into a `CallRequestInbox` entry.
///
/// `#if os(iOS)` is a platform fork, not a version gate: LiveCommunicationKit —
/// the framework whose Recents these donations serve — is macOS-unavailable
/// outright, so there is nothing on macOS for a donation to feed.
public enum CallActivity {
    /// The class name of `INStartCallIntent`, which is the activity type the
    /// system delivers a Recents redial under. Copied, never retyped — it is
    /// declared a second time in `Apps/Project.swift`'s `NSUserActivityTypes`,
    /// and `CallProjectLockstepTests` holds the pair together.
    public static let activityType = "INStartCallIntent"

    #if os(iOS)
        /// Donates "the user called this robot", so Recents and Siri can offer
        /// it back. The handle's value is the robot's `deduplicationKey` (rule
        /// 4: identity, never an address); the display name is what the
        /// Recents row shows.
        static func donate(robotID: String, robotName: String?) {
            let handle = INPersonHandle(value: robotID, type: .unknown)
            let person = INPerson(
                personHandle: handle,
                nameComponents: nil,
                displayName: robotName,
                image: nil,
                contactIdentifier: nil,
                customIdentifier: robotID
            )
            let intent = INStartCallIntent(
                callRecordFilter: nil,
                callRecordToCallBack: nil,
                audioRoute: .unknown,
                destinationType: .normal,
                contacts: [person],
                callCapability: .videoCall
            )
            INInteraction(intent: intent, response: nil).donate(completion: nil)
        }

        /// The robot a Recents redial names, out of the relaunch activity —
        /// `nil` for an activity that is not a start-call intent at all.
        static func robotID(from activity: NSUserActivity) -> String? {
            guard let intent = activity.interaction?.intent as? INStartCallIntent else { return nil }
            let person = intent.contacts?.first
            return person?.customIdentifier ?? person?.personHandle?.value
        }
    #else
        static func donate(robotID: String, robotName: String?) {}

        static func robotID(from activity: NSUserActivity) -> String? {
            nil
        }
    #endif
}

import AppIntents
import ReachyUI
import ReachyWidgetUI

/// "Call Reachy" — opens the robot's camera and unmutes the microphone, which
/// is what a call to a telepresence robot *is* (issue #78). The heavy lifting
/// is `RootCallLifecycle`'s: this intent only posts into `CallRequestInbox`,
/// the way a Recents redial does, so both entry points walk one path.
///
/// **In the app target, and it must stay here.** Every other intent lives in
/// `ReachyWidgetUI` so the widget extension can reach it — but this one opens
/// the app, and `openAppWhenRun` errors at runtime when an intent runs in an
/// appex (the `WakeRobotIntent` comment carries the details; `supportedModes`
/// is the iOS 26 replacement and this app deploys to 18). Living here keeps it
/// out of the extension's `Metadata.appintents` entirely. It is the first
/// intent extracted from the app target's own sources —
/// `Scripts/check-appintents-metadata.sh` counts it in `REQUIRED_APP_ACTIONS`.
///
/// Cross-platform deliberately, though LiveCommunicationKit is not: that script
/// checks the **macOS** app bundle too, so an `#if os(iOS)` here would fail the
/// macOS release build. On macOS the request routes identically — Live tab,
/// camera, microphone on — just without the system call framing around it,
/// which is honest behavior rather than a stub.
struct CallRobotIntent: AppIntent {
    static let title: LocalizedStringResource = "Call Reachy Mini"
    static let description = IntentDescription(
        "Opens the robot's camera and unmutes your microphone so you can talk through its speaker."
    )
    static let openAppWhenRun = true

    /// Optional like every robot parameter here: unfilled is "the connected
    /// robot", which is what keeps the bare Siri phrase working.
    @Parameter(title: "Robot")
    var robot: RobotEntity?

    init() {}

    @MainActor
    func perform() async throws -> some IntentResult {
        // An identity, never an address (rule 4) — and checked now so a robot
        // this app has since forgotten fails with words rather than opening the
        // app onto a request that can never route.
        guard robot == nil || RobotIntentTarget.knownRobot(id: robot?.id) != nil else {
            throw RobotIntentError.noKnownRobot
        }
        CallRequestInbox.shared.receive(robotID: robot?.id)
        return .result()
    }
}

